from taf.ue.plugin.mtk.commands import CFUN
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable


class Reboot(ActionSequenceVerifiable):

    def __init__(self, at_executor=None, verifier=None):

        self._at_executor = at_executor
        self._verifier = verifier

    def _generate_command_sequence(self):
        return [CFUN(self._at_executor, 1, 1)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()
